\"\"\"OpenAI Responses API client using only the Python standard library.

Usage:
    export OPENAI_API_KEY='sk-...'
    python -c \"import openai_client; print(openai_client.ask('Hello"'!'"'))\"
\"\"\"

import json
import os
import urllib.request
import urllib.error


BASE_URL = \"https://api.openai.com/v1/responses\"
DEFAULT_MODEL = \"gpt-4o\"


class OpenAIError(Exception):
    \"\"\"Raised when the API returns an error or the key is missing.\"\"\"


def _api_key() -> str:
    key = os.environ.get(\"OPENAI_API_KEY\")
    if not key:
        raise OpenAIError(
            \"OPENAI_API_KEY environment variable is not set\"
        )
    return key


def ask(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    instructions: str | None = None,
    **extra_body: object,
) -> str:
    \"\"\"Send a text prompt to the Responses API and return the output text.

    Parameters
    ----------
    prompt:
        The user message to send.
    model:
        OpenAI model identifier (default: gpt-4o).
    instructions:
        Optional system-level instruction for the model.
    **extra_body:
        Any additional keys passed directly in the request body
        (e.g. temperature=0.7, max_output_tokens=256).

    Returns
    -------
    The model's response text.

    Raises
    ------
    OpenAIError
        If the API key is missing or the request fails.
    urllib.error.URLError
        On network / connectivity errors.
    \"\"\"
    key = _api_key()
    body = {\"model\": model, \"input\": prompt}
    if instructions is not None:
        body[\"instructions\"] = instructions
    body.update(extra_body)

    data = json.dumps(body, ensure_ascii=False).encode(\"utf-8\")
    req = urllib.request.Request(
        BASE_URL,
        data=data,
        headers={
            \"Authorization\": f\"Bearer {key}\",
            \"Content-Type\": \"application/json\",
        },
        method=\"POST\",
    )

    try:
        with urllib.request.urlopen(req) as resp:
            result = json.loads(resp.read().decode(\"utf-8\"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode(\"utf-8\", errors=\"replace\")
        raise OpenAIError(
            f\"HTTP {exc.code} from OpenAI API: {detail}\"
        ) from exc

    # Parse the response — the Responses API returns a list of output items.
    try:
        texts: list[str] = []
        for item in result.get(\"output\", []):
            if item.get(\"type\") == \"message\":
                for content in item.get(\"content\", []):
                    if content.get(\"type\") == \"output_text\":
                        texts.append(content[\"text\"])
        return \"\\n\".join(texts)
    except (KeyError, TypeError) as exc:
        raise OpenAIError(
            f\"Unexpected response structure: {json.dumps(result, indent=2)}\"
        ) from exc


def stream(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    instructions: str | None = None,
    **extra_body: object,
) -> list[str]:
    \"\"\"Same as "'``ask`` but returns a list of text chunks for streaming use.

    This is a convenience wrapper that sets ``stream=True`` and collects
    the ``output_text.delta`` fragments from server-sent events.  The
    concatenation of the returned list equals what ``ask`` would return.
    """
    key = _api_key()
    body = {
        "model": model,
        "input": prompt,
        "stream": True,
    }
    if instructions is not None:
        body["instructions"] = instructions
    body.update(extra_body)

    data = json.dumps(body, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(
        BASE_URL,
        data=data,
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )

    chunks: list[str] = []
    try:
        with urllib.request.urlopen(req) as resp:
            buffer = b""
            while True:
                chunk = resp.read(4096)
                if not chunk:
                    break
                buffer += chunk
                while b"'"\\n\" in buffer:
                    line, buffer = buffer.split(b\"\\n\", 1)
                    line = line.decode(\"utf-8\").strip()
                    if not line:
                        continue
                    if line.startswith(\"data: \"):
                        payload = line[6:]
                        if payload == \"[DONE]\":
                            break
                        try:
                            ev = json.loads(payload)
                        except json.JSONDecodeError:
                            continue
                        for delta_item in ev.get(\"delta\", []):
                            if isinstance(delta_item, dict):
                                chunks.append(delta_item.get(\"text\", \"\"))
                        # Some streaming schemas nest the delta differently.
                        if \"delta\" not in ev:
                            for item in ev.get(\"output\", []):
                                if item.get(\"type\") == \"message\":
                                    for c in item.get(\"content\", []):
                                        if c.get(\"type\") == \"output_text\":
                                            chunks.append(
                                                c.get(\"delta\") or c.get(\"text\", \"\")
                                            )
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode(\"utf-8\", errors=\"replace\")
        raise OpenAIError(
            f\"HTTP {exc.code} from OpenAI API: {detail}\"
        ) from exc

    return chunks
PYEOF"

